def count_equivalence_classes(S):
    n = len(S)
    dp = [[0] * n for _ in range(n)]
    equivalence_classes = set()

    for i in range(n):
        for j in range(i, n):
            substring = S[i:j+1]
            # Check if the substring has an even number of '1's
            ones_count = substring.count('1')
            if ones_count % 2 == 0:
                dp[i][j] = 1
                equivalence_classes.add(substring)

    return len(equivalence_classes)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        S = data[index]
        index += 1
        results.append(count_equivalence_classes(S))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
